import { query } from '@anthropic-ai/claude-agent-sdk';
for await (const message of query({
  prompt: 'Analyze this code',
  options: { maxTurns: 3 }
})) {
  console.log(message);
}

// Continue mode (simplest)
for await (const msg of query({ prompt: 'First', options: { continue: false } })) {}
for await (const msg of query({ prompt: 'Follow-up', options: { continue: true } })) {}

// Streaming input
async function* gen() {
  yield { role: 'user', content: 'First' };
  yield { role: 'user', content: 'Follow-up' };
}
for await (const msg of query({ prompt: gen() })) {}

async function* messageGenerator() {
  yield { role: 'user', content: 'First question' };
  yield { role: 'user', content: 'Follow-up question' };
}
for await (const message of query({
  prompt: messageGenerator(),
  options: { maxTurns: 3 }
})) {
  console.log(message);
}

const q = query({ prompt: 'Start work', options: { maxTurns: 10 } });
// Later, to stop:
await q.interrupt();

// Capture
let sessionId;
for await (const message of query({
  prompt: 'Analyze',
  options: { allowedTools: ['Read'] }
})) {
  if (message.type === 'result') {
    sessionId = message.session_id;
  }
}
// Resume
for await (const msg of query({
  prompt: 'Continue',
  options: { resume: sessionId }
})) {}
// Fork
for await (const msg of query({
  prompt: 'Try alternative',
  options: { resume: sessionId, forkSession: true }
})) {}

let forkedId;
for await (const msg of query({
  prompt: 'Explore OAuth2 instead',
  options: { resume: sessionId, forkSession: true }
})) {
  if (msg.type === 'system' && msg.subtype === 'init') {
    forkedId = msg.session_id; // Different from original
  }
}
// Original stays intact
for await (const msg of query({
  prompt: 'Continue JWT path',
  options: { resume: sessionId }
})) {}

for await (const msg of query({prompt: '...'})) {
  if (msg.type === 'system') { /* init/capabilities */ }
  else if (msg.type === 'stream_event') { /* raw API event */ }
  else if (msg.type === 'result') { /* usage & cost */ }
}

if (msg.type === 'system') {
  console.log(msg.model); // e.g. 'claude-opus-4-1-20250805'
  console.log(msg.permissionMode); // 'dontAsk' | 'AskUserQuestion' | etc
  console.log(msg.capabilities); // ['interrupt_receipt_v1', ...]
}

if (msg.type === 'result') {
  console.log(msg.total_cost_usd); // $0.00123
  console.log(msg.usage.input_tokens);
  console.log(msg.usage.cache_read_input_tokens);
  for (const [model, stats] of Object.entries(msg.modelUsage)) {
    console.log(`${model}: $${stats.costUSD}`);
  }
}

if (msg.type === 'assistant') {
  const msgId = msg.message.id;
  const tokens = msg.message.usage.input_tokens;
  const contentBlocks = msg.message.content; // text, tool_use, thinking
}
if (msg.type === 'stream_event' && msg.event.type === 'content_block_delta') {
  console.log(msg.event.delta.text); // partial text chunk
}

const options = { includePartialMessages: true };
for await (const msg of query({prompt: '...', options})) {
  if (msg.type === 'stream_event') {
    if (msg.event.type === 'content_block_delta') {
      console.log(msg.event.delta); // {type: 'text_delta', text: 'chunk'}
    }
  }
}

if (msg.type === 'task_progress') {
  console.log(`Task ${msg.task_id}: ${msg.status}`);
  if (msg.summary) console.log(msg.summary);
}
if (msg.type === 'assistant' && msg.parent_tool_use_id) {
  console.log(`Subagent output from Agent call ${msg.parent_tool_use_id}`);
}

if (msg.type === 'hook_started') {
  console.log(`Hook executing: ${msg.hook_event.name}`);
}
if (msg.type === 'hook_progress') {
  console.log(`Progress:`, msg.progress);
}

if (msg.type === 'control_request') {
  if (msg.request.type === 'ask_user_question') {
    console.log(msg.request.question); // 'Allow Bash execution?'
    // Send control_response with request_id and approval
  }
}

if (msg.type === 'system' && msg.subtype === 'plugin_install') {
  if (msg.status === 'failed') console.error(msg.error);
}
if (msg.type === 'system' && msg.subtype === 'api_retry') {
  console.log(`Retry ${msg.attempt}/${msg.max_retries} in ${msg.retry_delay_ms}ms`);
}

if (msg.type === 'commands_changed') {
  console.log('Available commands now:', msg.commands.map(c => c.name));
}

// Use modelUsage for accurate multi-model accounting
for (const [model, usage] of Object.entries(msg.modelUsage)) {
  console.log(`${model}: input=${usage.inputTokens}, cache_read=${usage.cacheReadInputTokens}`);
}
// Do NOT use usage field with subagents; use total_cost_usd or modelUsage

import { app, safeStorage } from 'electron';

await app.whenReady();
if (await safeStorage.isAsyncEncryptionAvailable()) {
  const encrypted: Buffer = await safeStorage.encryptStringAsync(apiKey);
  // persist encrypted (see base64 item)
  const { result, shouldReEncrypt } = await safeStorage.decryptStringAsync(encrypted);
  if (shouldReEncrypt) {
    const reEncrypted = await safeStorage.encryptStringAsync(result);
    // overwrite the persisted value
  }
}

async function canPersistSecrets(): Promise<boolean> {
  if (!(await safeStorage.isAsyncEncryptionAvailable())) return false;
  if (process.platform === 'linux' && safeStorage.getSelectedStorageBackend() === 'basic_text') {
    return false; // hardcoded-password 'encryption' == plaintext-equivalent
  }
  return true;
}

// persist (e.g. into SQLite TEXT column or JSON)
const b64: string = (await safeStorage.encryptStringAsync(secret)).toString('base64');

// restore
const { result, shouldReEncrypt } = await safeStorage.decryptStringAsync(Buffer.from(b64, 'base64'));
if (shouldReEncrypt) {
  const next = (await safeStorage.encryptStringAsync(result)).toString('base64');
  // overwrite stored b64 with next
}

